    public void start(BundleContext context) throws Exception
    {
        log.info("Activating bundle " + context.getBundle().getSymbolicName());

        // get bundle classloader
        //var bundle = context.getBundle();
        //var bundleWiring = bundle.adapt(BundleWiring.class);
        //var bundleClassLoader = bundleWiring.getClassLoader();
        var bundleClassLoader = this.getClass().getClassLoader();

        // register all module providers as OSGi services
        var modules = ServiceLoader.load(IModuleProvider.class, bundleClassLoader);
        modules.forEach(m -> {
            log.info("Registering module: " + m.getModuleName());
            context.registerService(IModuleProvider.class, m, null);
        });
    }"},{"id":"c360.semsource-870e09.workspace.java.method.sensorhub-core-osgi-src-main-java-org-sensorhub-impl-osgi-SensorHubOsgi-java-SensorHubOsgi-main","body":"    public static void main(String[] args) throws Exception
    {
        // parse args
        var argSet = new HashMap<String,String>();
        for (int i = 1; i < args.length; i++)
        {
            var kvp = args[i].split("=");
            argSet.put(kvp[0], kvp.length > 1 ? kvp[1] : null);
        }
        var oshConfig = args.length > 0 ? args[0] : null;
        var clearCache = argSet.containsKey("-clearCache");
        var autoDeployDir = argSet.computeIfAbsent("-autoDeployDir", k -> DEFAULT_AUTODEPLOY_DIR);
        var bundleCacheDir = argSet.computeIfAbsent("-bundleCacheDir", k -> DEFAULT_BUNDLECACHE_DIR);

        // check args
        if (oshConfig == null)
        {
            // print usage
            System.out.println("Usage: SensorHubOsgi CONFIG_FILE [OPTION]\n");
            System.out.println("Options:");
            System.out.println("\\t-clearCache        Clear the OSGi bundle cache");
            System.out.println("\\t-autoDeployDir     Path of directory where bundles will be auto-deployed");
            System.out.println("\\t-bundleCacheDir    Path of bundle cache directory");
            System.exit(1);
        }

        // create bundles directory
        new File(autoDeployDir).mkdir();

        // create osgi config
        var config = new HashMap<String,String>();
        if (clearCache)
            config.put(Constants.FRAMEWORK_STORAGE_CLEAN, Constants.FRAMEWORK_STORAGE_CLEAN_ONFIRSTINIT);
        config.put(Constants.FRAMEWORK_STORAGE, bundleCacheDir);
        config.put(Constants.FRAMEWORK_SYSTEMPACKAGES,
            "org.osgi.framework; version=1.10.0," +
            "org.osgi.framework.dto; version=1.8.0," +
            "org.osgi.framework.wiring; version=1.2.0," +
            //"org.osgi.dto; version=1.1.0," +
            "org.osgi.resource; version=1.0.0," +
            "org.osgi.util.tracker; version=1.5.2," +
            "org.osgi.service.packageadmin; version=1.2.0," +
            "org.osgi.service.startlevel; version=1.1.0," +
            "org.osgi.service.url; version=1.0.0");

        config.put(Constants.FRAMEWORK_BOOTDELEGATION,
            "javax.*,sun.*,com.sun.*," +
            "org.xml.*,org.w3c.*");

        config.put("org.sensorhub.config", oshConfig);

        // load framework
        var frameworkFactory = ServiceLoader.load(FrameworkFactory.class).iterator().next();
        var framework = frameworkFactory.newFramework(config);

        // register shutdown hook for a clean stop 
        Runtime.getRuntime().addShutdownHook(new Thread() {
            @Override
            public void run()
            {
                try
                {
                    framework.stop();
                    framework.waitForStop(20000);
                }
                catch (InterruptedException e)
                {
                    LOGGER.log(Level.SEVERE, "Thread was interrupted during OSGi shutdown");
                    Thread.currentThread().interrupt();
                }
                catch (Exception e)
                {
                    LOGGER.log(Level.SEVERE, "Error while shutting down OSGi framework", e);
                }
            }
        });

        // start framework
        framework.init();
        systemCtx = framework.getBundleContext();

        // install everything in auto-deploy folder
        File dir = new File(autoDeployDir);
        File[] bundleJarFiles = dir.listFiles(new FilenameFilter() {
            public boolean accept(File dir, String name) {
                return name.endsWith(".jar");
            }
        });
        for (var f: bundleJarFiles) {
            LOGGER.info("Installing bundle " + f);
            var bundle = systemCtx.installBundle(REF_PREFIX + f.toPath().toString());
            if (bundle.getHeaders().get("Fragment-Host") == null) {
                bundle.start();
            }
        }

        // start all installed bundles
        framework.start();

        // watch bundle folder
        try
        {
            var watcher = new DirectoryWatcher(Paths.get(autoDeployDir), StandardWatchEventKinds.ENTRY_CREATE);
            var watcherThread = new Thread(watcher);
            watcher.addListener(path -> {
                try
                {
                    var bundle = systemCtx.installBundle(REF_PREFIX + path.toString());
                    if (bundle.getHeaders().get("Fragment-Host") == null) {
                        bundle.start();
                    }
                }
                catch (BundleException e)
                {
                    LOGGER.log(Level.SEVERE, "Error installing bundle", e);
                }
            });
            watcherThread.start();
        }
        catch (IOException e)
        {
            LOGGER.log(Level.SEVERE, "Error creating watcher on bundle folder", e);
        }
    }"},{"id":"c360.semsource-870e09.workspace.java.file.sensorhub-core-osgi-src-test-java-org-sensorhub-impl-osgi-TestOsgi-java","body":""},{"id":"c360.semsource-870e09.workspace.java.class.sensorhub-core-osgi-src-test-java-org-sensorhub-impl-osgi-TestOsgi-java-TestOsgi","body":"public class TestOsgi
{
    private static String CACHE_FOLDER = "osgi-cache";


    protected Framework getFramework()
    {
        Iterator<FrameworkFactory> it = ServiceLoader.load(org.osgi.framework.launch.FrameworkFactory.class).iterator();
        assertTrue("No OSGI implementation found in classpath", it.hasNext());

        Map<String,String> osgiConfig = new HashMap<String,String>();
        //osgiConfig.put(AutoProcessor.AUTO_DEPLOY_DIR_PROPERY, "");
        osgiConfig.put("org.osgi.framework.storage", CACHE_FOLDER);
        osgiConfig.put("org.osgi.framework.storage.clean", "onFirstInit");
        Framework fw = it.next().newFramework(osgiConfig);

        return fw;
    }


    protected Bundle installBundle(Framework fw, String bundleURL, String bundleName) throws Exception
    {
        int numBundles = fw.getBundleContext().getBundles().length;

        // install bundle
        Bundle newBundle = fw.getBundleContext().installBundle(bundleURL);
        assertTrue("bundle should not be null", newBundle != null);        
        System.out.println("Bundle name is " + newBundle.getSymbolicName());

        // check that it was properly loaded
        assertEquals("Wrong number of loaded bundles", numBundles+1, fw.getBundleContext().getBundles().length);
        assertEquals("Unexpected bundle name", bundleName, newBundle.getSymbolicName());
        assertEquals("Bundle should be in INSTALLED state", Bundle.INSTALLED, newBundle.getState());

        return newBundle;
    }


    @Test
    public void test1StartStopFramework() throws Exception
    {
        Framework fw = getFramework();
        fw.start();
        Thread.sleep(500);
        fw.stop();
        fw.waitForStop(0);
    }


    @Test
    public void test2InstallBundle() throws Exception
    {
        Framework fw = getFramework();
        fw.start();

        // install bundle w/o dependency
        Bundle newBundle = installBundle(fw, getClass().getResource("/test-nodep.jar").toString(), "org.sensorhub.test");

        // attempt to start it
        newBundle.start();
        assertEquals("Bundle should be in ACTIVE state", Bundle.ACTIVE, newBundle.getState());

        fw.stop();
        fw.waitForStop(0);
    }


    @Test
    public void test3BundleDependencies() throws Exception
    {
        Framework fw = getFramework();
        fw.start();

        assertEquals("Wrong number of loaded bundles", 1, fw.getBundleContext().getBundles().length);

        // install 1st bundle
        installBundle(fw, getClass().getResource("/test-nodep.jar").toString(), "org.sensorhub.test");

        // install 2nd bundle
        Bundle bundle2 = installBundle(fw, getClass().getResource("/test-withdep.jar").toString(), "org.sensorhub.test2");

        bundle2.start();
        assertEquals("Bundle " + bundle2.getSymbolicName() + " should be in ACTIVE state", Bundle.ACTIVE, bundle2.getState());

        fw.stop();
        fw.waitForStop(0);
    }


    @AfterClass
    public static void cleanup()
    {
        try
        {
            FileUtils.deleteDirectory(new File(CACHE_FOLDER));
        }
        catch (IOException e)
        {
        }
    }
}"},{"id":"c360.semsource-870e09.workspace.java.var.lib-ogc-sensorml-core-src-main-java-org-vast-sensorML-AggregateProcessImpl-java-AggregateProcessImpl-components","body":"    protected OgcPropertyList<AbstractProcess> components = new OgcPropertyList<>(5);"},{"id":"c360.semsource-870e09.workspace.java.class.sensorhub-core-src-main-java-org-sensorhub-utils-OshBundleActivator-java-OshBundleActivator","body":"public abstract class OshBundleActivator implements BundleActivator
{
    protected static Logger log = LoggerFactory.getLogger(OshBundleActivator.class);


    @Override
    public void start(BundleContext context) throws Exception
    {
        log.info("Activating bundle " + context.getBundle().getSymbolicName());

        // get bundle classloader
        //var bundle = context.getBundle();
        //var bundleWiring = bundle.adapt(BundleWiring.class);
        //var bundleClassLoader = bundleWiring.getClassLoader();
        var bundleClassLoader = this.getClass().getClassLoader();

        // register all module providers as OSGi services
        var modules = ServiceLoader.load(IModuleProvider.class, bundleClassLoader);
        modules.forEach(m -> {
            log.info("Registering module: " + m.getModuleName());
            context.registerService(IModuleProvider.class, m, null);
        });
    }


    @Override
    public void stop(BundleContext context) throws Exception
    {
    }

